import {ContractError,validDate} from './cloud-contract.mjs';
import {attendanceId} from './attendance-contract.mjs';
import {validMonth} from './monthly-contract.mjs';
import {pagedRows} from './management-model.mjs';
export const basisBlockers={'no-member':'没有关联人员档案','missing-start-date':'请先补全入职日期','outside-employment':'所选月份不在已登记的在职期间','month-open':'月份尚未结束，请在下月核对'};
export function employmentPayload(v){const keys=['requestKey','expectedVersion','startDate','endDate','note'];if(!v||keys.some(k=>!Object.hasOwn(v,k))||Object.keys(v).some(k=>!keys.includes(k))||!Number.isSafeInteger(v.expectedVersion)||v.expectedVersion<1||typeof v.note!=='string'||!v.note.trim()||v.note.length>2000)throw new ContractError('请填写完整日期与变更说明。');attendanceId(v.requestKey);for(const k of ['startDate','endDate'])if(v[k]!==null&&(!validDate(v[k])||v[k]<'1900-01-01'||v[k]>'2199-12-31'))throw new ContractError('请核对在职日期。');if(v.endDate&&(!v.startDate||v.endDate<v.startDate))throw new ContractError('最后在职日不得早于入职日。');return {...v,note:v.note.trim()};}
export function adminReviewPayload(v){const keys=['requestKey','month','memberId','expectedReviewId','sourceHash','note','confirmed'];if(!v||keys.some(k=>!Object.hasOwn(v,k))||Object.keys(v).some(k=>!keys.includes(k))||!/^([a-f0-9]{64})$/.test(v.sourceHash||'')||typeof v.note!=='string'||!v.note.trim()||v.note.length>2000||v.confirmed!==true)throw new ContractError('请核对当月适用依据并填写说明。');attendanceId(v.requestKey);attendanceId(v.memberId);if(v.expectedReviewId!==null)attendanceId(v.expectedReviewId);validMonth(v.month);return {...v,note:v.note.trim()};}
export function personnelHistory(v){pagedRows(v);if(v.limit!==50)throw new ContractError();for(const r of v.rows)if(!r.id||!r.after_value||!Number.isFinite(Date.parse(r.created_at)))throw new ContractError();return v;}
export function adminReviewHistory(v){pagedRows(v);if(v.limit!==50)throw new ContractError();for(const r of v.rows){attendanceId(r.id);if(typeof r.note!=='string'||!Number.isFinite(Date.parse(r.created_at))||!r.source_snapshot)throw new ContractError();}return v;}
